const rows = $input.all().map(item => item.json);
const request = $('01 Receber demanda GG Relacionamento').first()?.json ?? {};

// Agrupar contatos por CNPJ
const accountMap = new Map();
for (const r of rows) {
  if (!accountMap.has(r.cnpj)) {
    accountMap.set(r.cnpj, {
      cnpj: r.cnpj,
      razao_social: r.razao_social,
      employees_count: Number(r.employees_count || 0),
      months_revenue_12m: Number(r.months_revenue_12m || 0),
      payroll_active: r.payroll_active,
      billing_active: r.billing_active,
      pix_active: r.pix_active,
      contacts: []
    });
  }
  if (r.contact_name) {
    accountMap.get(r.cnpj).contacts.push({
      id: r.contact_id,
      contact_name: r.contact_name,
      role: r.contact_role,
      phone: r.phone,
      email: r.email,
      is_decision_maker: r.is_decision_maker,
      key_interests: r.key_interests || [],
      known_objections: r.known_objections || [],
      last_contact_at: r.last_contact_at
    });
  }
}

const accounts = Array.from(accountMap.values());
const approaches = [];

for (const acc of accounts) {
  const mainContact = acc.contacts.find(c => c.is_decision_maker) || acc.contacts[0] || null;
  const contactName = mainContact?.contact_name || 'Decisor Financeiro';

  // Prioridade Folha
  if (acc.employees_count >= 20 && !acc.payroll_active) {
    approaches.push({
      account_ref: acc.cnpj,
      razao_social: acc.razao_social,
      target_product: 'FOLHA_DE_PAGAMENTO',
      contact_name: contactName,
      role: mainContact?.role || 'Diretor',
      approach: {
        objective: 'Apresentar plano de portabilidade da folha de pagamento (' + acc.employees_count + ' vidas) com suporte presencial da agência 6895.',
        opening: 'Olá, ' + contactName + '! Estruturei um formato sob medida para a folha do ' + acc.razao_social + ', onde a agência assume todo o suporte de abertura das contas.',
        questions: [
          'Qual o principal ponto de atrito do RH com o banco atual?',
          'Os colaboradores teriam interesse em crédito consignado exclusivo da agência?'
        ],
        next_step: 'Agendar reunião técnica com o RH para validação de layout CNAB.',
        requires_owner_approval: true
      },
      decision_authority: 'RAFAEL'
    });
  }
  // Prioridade Cobrança
  else if (acc.months_revenue_12m >= 1000000 && (!acc.billing_active || !acc.pix_active)) {
    approaches.push({
      account_ref: acc.cnpj,
      razao_social: acc.razao_social,
      target_product: 'COBRANCA_PIX',
      contact_name: contactName,
      role: mainContact?.role || 'Diretor',
      approach: {
        objective: 'Implantar pacote integrado de Cobrança e PIX Dinâmico com liquidação D+0 e redução de tarifas.',
        opening: 'Olá, ' + contactName + '! Preparamos uma condição de cobrança integrada para a ' + acc.razao_social + ' com liquidação D+0 e menor custo por boleto.',
        questions: [
          'Qual o percentual atual de recebimento via PIX versus boleto tradicional?',
          'O ERP da empresa já suporta boleto com QR Code PIX híbrido?'
        ],
        next_step: 'Enviar simulação de tarifas e agendar homologação de arquivo.',
        requires_owner_approval: true
      },
      decision_authority: 'RAFAEL'
    });
  }
}

const output = {
  schema_version: '1.0.0',
  request_id: request.request_id || ('req-rel-' + Date.now()),
  provided_by: 'GERENTE_GERAL_RELACIONAMENTO',
  operating_phase: 'CONTACT_LEVEL_ACTIVE',
  total_accounts_analyzed: accounts.length,
  contacts_mapped: rows.filter(r => r.contact_name).length,
  prioritized_approaches: approaches,
  summary: {
    folha_approaches_count: approaches.filter(a => a.target_product === 'FOLHA_DE_PAGAMENTO').length,
    cobranca_approaches_count: approaches.filter(a => a.target_product === 'COBRANCA_PIX').length,
    top_priority: approaches[0] || null
  },
  compliance_rule: 'Contato externo ou envio de mensagens exige autorização expressa de Rafael.',
  decision_authority: 'RAFAEL'
};

return [{ json: output }];
